mapper.sql:
${limitBefore} select distinct W.ID_ "taskId", W.EXECUTION_ID_ "executionId", W.PROC_INST_ID_ "processInstanceId", W.PROC_DEF_ID_ "processDefinitionId", W.NAME_ "activityName", W.DESCRIPTION_ "description" , W.TASK_DEF_KEY_ "activityId", W.START_TIME_ "beginTime", W.END_TIME_ "endTime", W.DUE_DATE_ "dueDate", W.FORM_KEY_ "formKey", W.TENANT_ID_ "tenantId", W.businessKey "businessKey", W.startUserId "startUserId", W.startUserName "startUserName", W.processStartTime "processStartTime", W.superProcessInstanceId "superProcessInstanceId", W.processEndTime "processEndTime", W.orgId "orgId", W.taskType "taskType", W.processDefineName "processDefineName", W.processDefineKey "processDefineKey", W.userComment "comment", W.classifyName "classifyName", W.classifyCode "classifyCode"
,
${field}
, row_number() over (ORDER BY W.ID_ ) rnk FROM ( select distinct RES.*, P.BUSINESS_KEY_ businessKey, P.START_USER_ID_ startUserId, P.START_TIME_ processStartTime, P.SUPER_PROCESS_INSTANCE_ID_ superProcessInstanceId, P.END_TIME_ processEndTime, arv.TEXT_ orgId, hv.TEXT_ taskType, R.NAME_ processDefineName, R.KEY_ processDefineKey, M.MESSAGE_ userComment, C.name classifyName, C.code classifyCode
, w.*
ORDER BY RES.END_TIME_ DESC )W ) SUB WHERE SUB.rnk >= #{firstRow} AND SUB.rnk < #{lastRow}

FROM ${prefix}act_hi_taskinst RES
INNER JOIN wf_hi_task_expand_data w ON RES.ID_ = w.task_id
AND RES.PROC_INST_ID_ = W.PROCESS_INST_ID
INNER JOIN ACT_HI_PROCINST P ON RES.PROC_INST_ID_ = P.PROC_INST_ID_
INNER JOIN ACT_RE_PROCDEF R ON RES.PROC_DEF_ID_ = R.ID_
LEFT JOIN ACT_HI_COMMENT M ON M.TASK_ID_ = RES.ID_ and RES.PROC_INST_ID_ = M.PROC_INST_ID_
INNER JOIN WF_PROCESS_CLASSIFY C ON C.id = R.CATEGORY_
LEFT JOIN act_ru_variable arv ON arv.PROC_INST_ID_ = RES.PROC_INST_ID_
	AND arv.NAME_='_START_USER_ORG_ID'
LEFT JOIN act_hi_varinst hv ON hv.TASK_ID_ = RES.ID_
AND hv.NAME_='_ADDED_TASK_TYPE'

  LEFT JOIN ACT_RU_IDENTITYLINK I ON I.TASK_ID_ = RES.ID_



  INNER JOIN (
  SELECT DISTINCT
  htk.PROC_INST_ID_,

    htk.TASK_DEF_KEY_,

  MAX( htk.END_TIME_ ) AS END_TIME_
  FROM
  act_hi_taskinst htk

    htk.DELETE_REASON_ != 'delete'
    AND htk.DELETE_REASON_ != 'reback'
    AND htk.DELETE_REASON_ != 'TansunBackDelete'

      AND htk.ASSIGNEE_ = #{userId}


  GROUP BY

    htk.TASK_DEF_KEY_,

  htk.PROC_INST_ID_
  ORDER BY
  htk.PROC_INST_ID_) singleHi ON RES.PROC_INST_ID_ = singleHi.PROC_INST_ID_
  AND RES.END_TIME_ = singleHi.END_TIME_



   	RES.DELETE_REASON_ !='delete' AND RES.DELETE_REASON_ !='reback' AND RES.DELETE_REASON_ !='TansunBackDelete'


	(RES.DELETE_REASON_ IS NULL OR (RES.DELETE_REASON_ !='delete' AND RES.DELETE_REASON_ !='reback' AND RES.DELETE_REASON_ !='TansunBackDelete'))



      AND ${condition}



    AND P.START_TIME_ BETWEEN #{processCreateTimeBefore} AND #{processCreateTimeAfter}


    AND P.START_TIME_ BETWEEN to_date(#{processCreateTimeBefore},'yy-mm-dd,hh24:mi:ss') AND to_date(#{processCreateTimeAfter},'yy-mm-dd,hh24:mi:ss')


    AND RES.PROC_INST_ID_ = #{processInstanceId}


    AND RES.PROC_DEF_ID_ = #{processDefinitionId}


    AND RES.TASK_DEF_KEY_ = #{taskDefinitionKey}


    AND RES.NAME_ LIKE #{taskNameLike}


    AND RES.ID_ = #{taskId}


    AND (
          RES.ASSIGNEE_ = #{userId}

              OR (
                   RES.ASSIGNEE_ IS NULL
              AND (
                   I.USER_ID_ = #{userId}
                   OR I.GROUP_ID_ IN (
                   SELECT
                    g.GROUP_ID_
                   FROM
                    ACT_ID_MEMBERSHIP g
                   WHERE
                    g.USER_ID_ = #{userId}
                   )
                  )
              )

    )


    AND RES.DELETE_REASON_ != #{isTerminateProcess}


    AND p.END_TIME_ is not null


    AND p.END_TIME_ is null



    AND p.END_TIME_ is not null


    AND p.END_TIME_ is null


    AND RES.END_TIME_ is not null


    AND RES.TENANT_ID_ = #{tenantId}


    AND P.BUSINESS_KEY_ = #{businessKey}


  AND P.BUSINESS_KEY_ like #{businessKeyLike}


    AND  R.NAME_ = #{processDefineName}


    AND  R.NAME_ like #{processDefineNameLike}


    AND  R.KEY_ = #{processDefineKey}


    AND  R.KEY_ like #{processDefineKeyLike}


    AND R.KEY_ in

      #{processDefineKey}



        AND RES.TENANT_ID_ IN

            #{tenantId}



    AND C.code = #{classifyCode}



      AND RES.START_TIME_ <= to_timestamp(#{createTimeBefore}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')


      AND RES.START_TIME_ >= to_timestamp(#{createTimeAfter}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')


      AND RES.END_TIME_ <= to_timestamp(#{endTimeBefore}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')


      AND RES.END_TIME_ >= to_timestamp(#{endTimeAfter}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')




      AND RES.START_TIME_ <= #{createTimeBefore}


      AND RES.START_TIME_ >= #{createTimeAfter}


      AND RES.END_TIME_ <= #{endTimeBefore}


      AND RES.END_TIME_ >= #{endTimeAfter}



    AND

      RES.TASK_DEF_KEY_ != #{activityId}



    AND

      RES.NAME_ != #{activityName}


   AND RES.END_TIME_ is not null

    FROM ${prefix}act_hi_taskinst RES
    INNER JOIN wf_hi_task_expand_data w ON RES.ID_ = w.task_id



        and RES.ASSIGNEE_ is not null


        and RES.ASSIGNEE_ is null




      INNER JOIN (
      SELECT DISTINCT
      htk.PROC_INST_ID_,

        htk.TASK_DEF_KEY_,

      MAX( htk.END_TIME_ ) AS END_TIME_
      FROM
      act_hi_taskinst htk

        htk.DELETE_REASON_ != 'delete'
        AND htk.DELETE_REASON_ != 'reback'
        AND htk.DELETE_REASON_ != 'TansunBackDelete'

          AND htk.ASSIGNEE_ = #{userId}


      GROUP BY

        htk.TASK_DEF_KEY_,

      htk.PROC_INST_ID_
      ORDER BY
      htk.PROC_INST_ID_) singleHi ON RES.PROC_INST_ID_ = singleHi.PROC_INST_ID_
      AND RES.END_TIME_ = singleHi.END_TIME_



      RES.DELETE_REASON_ !='delete'
      AND RES.DELETE_REASON_ !='reback'
      AND RES.DELETE_REASON_ !='TansunBackDelete'

        AND RES.PROC_INST_ID_ = #{processInstanceId}


        AND RES.PROC_DEF_ID_ = #{processDefinitionId}


        AND RES.TASK_DEF_KEY_ = #{taskDefinitionKey}


        AND RES.NAME_ LIKE #{taskNameLike}


        AND RES.ID_ = #{taskId}


        AND RES.ASSIGNEE_ = #{userId}


        AND RES.DELETE_REASON_ != #{isTerminateProcess}



        AND RES.TENANT_ID_ = #{tenantId}



	        AND RES.TENANT_ID_ IN

	          #{tenantId}





          AND RES.START_TIME_ <= to_timestamp(#{createTimeBefore}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')


          AND RES.START_TIME_ >= to_timestamp(#{createTimeAfter}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')


          AND RES.END_TIME_ <= to_timestamp(#{endTimeBefore}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')


          AND RES.END_TIME_ >= to_timestamp(#{endTimeAfter}||'.999','YYYY-MM-DD HH24:MI:ss.ff3')




          AND RES.START_TIME_ <= #{createTimeBefore}


          AND RES.START_TIME_ >= #{createTimeAfter}


          AND RES.END_TIME_ <= #{endTimeBefore}


          AND RES.END_TIME_ >= #{endTimeAfter}



        AND

          RES.TASK_DEF_KEY_ != #{activityId}



        AND

          RES.NAME_ != #{activityName}


       AND RES.END_TIME_ is not null

mapper.update:
UPDATE wf_hi_task_expand_data
SET PROCESS_END_TIME = #{endTime}
WHERE
  TASK_ID IN

    #{taskId}

mapper.select:
SELECT ID, TASK_EXPAND_PLAN_ID, PROCESS_INST_ID, PROCESS_DEF_ID, TASK_ID, TASK_NODE_ID, FIELD01, FIELD02, FIELD03, FIELD04, FIELD05, FIELD06, FIELD07, FIELD08, FIELD09, FIELD10, FIELD11, FIELD12, FIELD13, FIELD14, FIELD15, FIELD16, FIELD17, FIELD18, FIELD19, FIELD20 FROM WF_HI_TASK_EXPAND_DATA
TASK_ID = #{taskId}
TASK_ID IN
#{taskId}
